a_values = range(8, 12)

results = {}

for a in a_values:
    # Calculate k = n - 2a
    k = n - 2 * a

    # Check constraints for the binomial coefficient indices
    # We need to check if k-1 <= a-1, which means k <= a.
    # k = 23 - 2a. We need 23 - 2a <= a, so 23 <= 3a. This is guaranteed by a >= 8 (23/3 ~ 7.66).
    # We also need k-1 >= 0, so k >= 1. This is guaranteed by a <= 11 (23 - 22 = 1).

    try:
        # Calculate C = binomial coefficient: C(a-1, k-1)
        C = math.comb(a - 1, k - 1)

        # Check divisibility: k | C
        is_divisible = C % k == 0

        results[a] = {
            "k": k,
            "C": C,
            "divisible": is_divisible
        }
    except ValueError as e:
        results[a] = {"error": str(e)}

# Print results for verification
