import math

def check_n(n):
    """
    Checks if the condition holds for a given n.
    Condition: For any positive integer a such that floor(n/a) = 2,
    k = n - 2a must divide binomial(a-1, k-1).
    """
    if n < 2:
        return True

    # Determine the range of a: n/3 < a <= n/2
    a_min = math.floor(n / 3) + 1
    a_max = math.floor(n / 2)

    for a in range(a_min, a_max + 1):
        k = n - 2 * a

        if k == 0:
            continue

        if k == 1:
            # Condition 1 | binomial(a-1, 0) is always true.
            continue

        m = a - 1
        r = k - 1

        # If r > m, binomial(m, r) = 0. Since k > 1, k | 0 is true.
        if r > m:
            continue

        # Calculate binomial coefficient using math.comb (Python >= 3.8)
        # We assume a modern environment supports math.comb.
        try:
            binom_coeff = math.comb(m, r)
        except AttributeError:
            # Fallback calculation for compatibility
            def combination(n, k):
                if k < 0 or k > n:
                    return 0
                if k == 0 or k == n:
                    return 1
                if k > n // 2:
                    k = n - k
                res = 1
                for i in range(k):
                    res = res * (n - i) // (i + 1)
                return res
            binom_coeff = combination(m, r)


        if binom_coeff % k != 0:
            print(f"FAILURE found for n={n}, a={a}, k={k}. Check: {k} | {binom_coeff} is False.")
            return False

    return True

# Search for counterexamples for n < 50, coprime to 6.
N_LIMIT = 50
print(f"Starting search for n < {N_LIMIT} coprime to 6...")

found_counterexample = False
for n in range(2, N_LIMIT):
    if math.gcd(n, 6) == 1:
        if not check_n(n):
            found_counterexample = True
            break

